#!/usr/bin/env bash
set -u
export LC_ALL=C
if [ $# -ne 1 ]; then
  echo "usage: $0 <deps-file>" >&2
  exit 2
fi
f="$1"
awk '
function trim(s) {
  sub(/^[ \t\r]+/, "", s)
  sub(/[ \t\r]+$/, "", s)
  return s
}
{
  line = $0
  p = index(line, "#")
  if (p > 0) line = substr(line, 1, p-1)
  if (line ~ /^[ \t\r]*$/) next
  c = index(line, ":")
  if (c == 0) next
  pkgpart = substr(line, 1, c-1)
  restpart = substr(line, c+1)
  pkg = trim(pkgpart)
  if (pkg == "") next
  if (pkg ~ /[ \t\r]/) next
  pkgs[pkg] = 1
  n = split(restpart, arr, /[ \t\r]+/)
  for (i = 1; i <= n; i++) {
    d = arr[i]
    if (d == "") continue
    pkgs[d] = 1
    key = pkg SUBSEP d
    if (!(key in hasdep)) {
      hasdep[key] = 1
      cnt[pkg]++
      deplist[pkg SUBSEP cnt[pkg]] = d
    }
  }
}
END {
  np = asorti(pkgs, sorted)
  for (i = 1; i <= np; i++) remaining[sorted[i]] = 1
  while (1) {
    best = ""
    for (i = 1; i <= np; i++) {
      p = sorted[i]
      if (!(p in remaining)) continue
      ok = 1
      c = cnt[p] + 0
      for (j = 1; j <= c; j++) {
        q = deplist[p SUBSEP j]
        if (!(q in emitted)) { ok = 0; break }
      }
      if (ok) { best = p; break }
    }
    if (best == "") break
    print best
    emitted[best] = 1
    delete remaining[best]
  }
  nr = asorti(remaining, remsorted)
  if (nr > 0) {
    msg = "cycle: " remsorted[1]
    for (i = 2; i <= nr; i++) msg = msg " " remsorted[i]
    print msg > "/dev/stderr"
    exit 1
  }
}
' "$f"

